/* =====================================================================
   figures-anorectal.js — base sheets for the anorectal sepsis category.

   Ball's own line drawings, embedded as PNG data URIs for the same
   reason as figures-original.js: the app then works from any origin and
   the canvas export never taints. An earlier version of this file drew
   the same three views as vector by hand; it was not good enough to put
   in front of a fellow, and this replaced it.

   Three views, because an abscess is named for the space it fills and
   no single section shows every space:

     ar_spaces_pelvic    the pelvic floor from above — the sheet a
                         horseshoe is drawn across
     ar_spaces_coronal   the spaces stacked outward from the lumen —
                         submucosal, intersphincteric, ischioanal,
                         supralevator, perianal
     ar_spaces_sagittal  the posterior spaces, which only a sagittal
                         section separates: retrorectal, supralevator,
                         deep postanal, superficial postanal

   ALL THREE SIT ON ONE CANVAS, 900 x 580, WITH THE INK SCALED TO THE
   SAME HEIGHT AND CENTRED.

   The printed set is a flex row that gives each figure an identical
   44 mm slot, so the rendered height is 44/ratio — identical only if the
   ratio is. Drawn at their own sizes, the near-square sagittal came out
   half as tall again as the other two and the three captions sat on
   three different lines. Normalising the canvas fixes the boxes;
   normalising the ink height inside it fixes the drawings, which is what
   the eye actually reads.

   Unlabelled on purpose: the naming is left to whoever holds the pen.
   ===================================================================== */

(function (global) {
  'use strict';

  var ADDED = {
    ar_spaces_pelvic: { short: 'Axial', th: 'อุ้งเชิงกราน มองจากด้านบน',
      en: 'Pelvic floor from above', w: 900, h: 580,
      png: 'data:image/png;base64,' },
    ar_spaces_coronal: { short: 'Coronal', th: 'ช่องรอบทวารหนัก ภาพตัดแนวหน้า',
      en: 'Anorectal spaces — coronal', w: 900, h: 580,
      png: 'data:image/png;base64,' },
    ar_spaces_sagittal: { short: 'Sagittal', th: 'ช่องด้านหลังทวารหนัก ภาพตัดแนวข้าง',
      en: 'Postanal and retrorectal spaces — sagittal', w: 900, h: 580,
      png: 'data:image/png;base64,' }
  };

  Object.keys(ADDED).forEach(function (k) { global.FIGURES[k] = ADDED[k]; });

  /* Axial, coronal, sagittal — the order the views are read in, and the
     order the other anorectal sets in this app already use. */
  global.FIGURE_DEFAULTS.anorectal =
    ['ar_spaces_pelvic', 'ar_spaces_coronal', 'ar_spaces_sagittal'];

})(window);
